237	        // E100 whenever any (ecosystem, native name) this path declares -- primary
238	        // or not -- is already owned by a different path; names both. Checked before
239	        // any promotion bookkeeping so a dual-manifest directory's non-primary name
240	        // (e.g. an npm sibling of a Cargo-primary package) is covered too, not just
241	        // each path's own primary name.
242	        if let Some((eco, id)) = list.iter().find(|(eco, id)| {
243	            self.native_owner
244	                .get(&(*eco, id.name().to_string()))
245	                .is_some_and(|p| *p != rel_path)
246	        }) {
247	            let owner_path = self.native_owner[&(*eco, id.name().to_string())].clone();
248	            return Err(GraphError::DuplicatePackage {
249	                id: id.clone(),
250	                paths: vec![owner_path, rel_path],
251	            });
252	        }
253	        for (eco, id) in &list {
254	            self.native_owner
255	                .insert((*eco, id.name().to_string()), rel_path.clone());
256	        }
257	
258	        let mut primary_id = list[0].1.clone();
259	        let (this_claiming, this_native_keys) = compute_claiming_ecosystems_and_native_keys(&list, &primary_id);
260	        self.claiming_ecosystems.insert(rel_path.clone(), this_claiming.clone());
261	        self.path_native_keys.insert(rel_path.clone(), this_native_keys);
262	        self.primary_ecosystems.insert(rel_path.clone(), list[0].0);
263	
264	        let mut branch_ii_promoted = false;
265	        if self.promoted_siblings.contains_key(primary_id.name()) {
266	            let this_set = self.claiming_ecosystems.get(&rel_path).cloned().unwrap_or_default();
267	            let promoted_id = PackageId::Prefixed {
268	                ecosystem: self.primary_ecosystems[&rel_path],
269	                name: primary_id.name().to_string(),
270	            };
271	            self.promoted_siblings
272	                .entry(primary_id.name().to_string())
273	                .or_default()
274	                .push((promoted_id.clone(), this_set));
275	            primary_id = promoted_id;
276	            branch_ii_promoted = true;
277	        }
278	
279	        if !branch_ii_promoted {
280	            self.index
281	                .bare
282	                .insert(primary_id.name().to_string(), primary_id.clone());
283	        }
284	
285	        let mut decls = Vec::new();
286	        for (eco, id) in &list {
287	            let (fmt, filename) = match eco {
288	                Ecosystem::Cargo => (ManifestFormat::CargoToml, "Cargo.toml"),
289	                Ecosystem::Npm => (ManifestFormat::PackageJson, "package.json"),
290	                Ecosystem::Pypi => (ManifestFormat::PyprojectToml, "pyproject.toml"),
291	                _ => (ManifestFormat::PackageJson, "package.json"),
292	            };
293	            let manifest_rel = rel_path.join(filename);
294	            let canonical_decl = match ManifestDecl::new(manifest_rel.clone(), ManifestRole::Canonical, fmt) {
295	                Ok(decl) => {
296	                    decls.push(decl.clone());
297	                    Some(decl)
298	                }
299	                Err(error) => {
300	                    self.unresolved
301	                        .push(unresolved(&manifest_rel, "declare its manifest", error));
302	                    None
303	                }
304	            };
305	            // For napi platform packages (os + cpu constraints in package.json),
306	            // also push a Platform-role decl so release derivation can route them
307	            // as platform publishes instead of main packages. Reuses
308	            // the canonical decl's manifest handle via the shared
309	            // `manifest_cache` (`npm_role()`) instead of a second, raw
310	            // `fs::read` of the same package.json -- the handle opened here
311	            // is the same one `publish_targets`/`iter_dependencies` reuse
312	            // further down.
313	            if *eco == Ecosystem::Npm {
314	                let opened = canonical_decl
315	                    .as_ref()
316	                    .map(|decl| open_cached(self.manifest_cache, decl, self.ctx));
317	                let manifest = match opened {
318	                    Some(Ok(manifest)) => Some(manifest),
319	                    Some(Err(error)) => {
320	                        self.unresolved.push(unresolved(
321	                            &manifest_rel,
322	                            "open its manifest to read its platform role",
323	                            error,
324	                        ));
325	                        None
326	                    }
327	                    None => None,
328	                };
329	                let role = manifest
330	                    .and_then(|m| m.npm_role())
331	                    .map(|npm_role| match npm_role {
332	                        callisto_manifests::NpmRole::Platform { platform, arch, abi } => {
333	                            ManifestRole::Platform { platform, arch, abi }
334	                        }
335	                    })
336	                    .unwrap_or(ManifestRole::Canonical);
337	                if let ManifestRole::Platform { .. } = role {
338	                    match ManifestDecl::new(manifest_rel.clone(), role.clone(), fmt) {
339	                        Ok(platform_decl) => decls.push(platform_decl),
340	                        Err(error) => {
341	                            self.unresolved
342	                                .push(unresolved(&manifest_rel, "declare its platform manifest", error))
343	                        }
344	                    }
345	                    // `id` is this manifest's own npm identity, resolved from its
346	                    // own `name` field -- distinct from `primary_id` whenever a
347	                    // higher-priority ecosystem (Cargo) shares this directory.
348	                    // Config authors reference the platform package by
349	                    // its own name in `[[fixed-group]] members`, so that must be
350	                    // the index key; `primary_id` is who it belongs to.
351	                    self.index
352	                        .platform
353	                        .insert(id.name().to_string(), (primary_id.clone(), manifest_rel, role));
354	                    self.path_platform_keys
355	                        .entry(rel_path.clone())
356	                        .or_default()
357	                        .push(id.name().to_string());
358	                }
359	            }
360	            self.index
361	                .native
362	                .insert((*eco, id.name().to_string()), primary_id.clone());
363	            if id.name() == primary_id.name() {
364	                self.index
365	                    .prefixed
366	                    .insert((*eco, id.name().to_string()), primary_id.clone());
367	            }
368	        }
369	
370	        let current_decls = decls.clone();
371	        if let Some((existing_path, existing_decls)) = self
372	            .package_manifest_decls
373	            .insert(primary_id.clone(), (rel_path.clone(), decls))
374	        {
375	            self.promotion_rekey(primary_id, existing_path, existing_decls, rel_path, current_decls);
376	        }
377	        Ok(())
378	    }
379	
380	    /// A second path just claimed the bare name `primary_id`, so both paths are promoted to ecosystem-prefixed ids
381	    /// and every key already stored under the stale bare id is re-keyed.
382	    fn promotion_rekey(
383	        &mut self,
384	        primary_id: PackageId,
385	        existing_path: PathBuf,
386	        existing_decls: Vec<ManifestDecl>,
387	        rel_path: PathBuf,
388	        current_decls: Vec<ManifestDecl>,
389	    ) {
390	        // Both paths' claiming ecosystems are guaranteed disjoint here: an
391	        // overlap would already have failed at the native_owner check above.
392	        let name = primary_id.name().to_string();
393	        // STALE-KEY REWRITE location (4): re-key package_manifest_decls under
394	        // each path's own newly-promoted Prefixed id, sourcing each path's own
395	        // decls -- captured via the `existing_decls` returned by `insert` above
396	        // and the `current_decls` clone taken before `insert` overwrote the map,
397	        // never via a `.get(&primary_id)` lookup after the fact (a lookup miss
398	        // there would silently substitute an empty Vec -- the
399	        // manifests-bleed bug).
400	        let existing_id = PackageId::Prefixed {
401	            ecosystem: self.primary_ecosystems[&existing_path],
402	            name: name.clone(),
403	        };
404	        let current_id = PackageId::Prefixed {
405	            ecosystem: self.primary_ecosystems[&rel_path],
406	            name: name.clone(),
407	        };
408	        self.package_manifest_decls
409	            .insert(existing_id.clone(), (existing_path.clone(), existing_decls));
410	        self.package_manifest_decls
411	            .insert(current_id.clone(), (rel_path.clone(), current_decls));
412	        self.package_manifest_decls.remove(&primary_id);
413	        // STALE-KEY REWRITE location (1): once a bare name is promoted,
414	        // it MUST NOT remain in index.bare.
415	        self.index.bare.remove(&name);
416	        // STALE-KEY REWRITE location (2): update index.native values
417	        // for all native keys declared by either path so they map to
418	        // their path's newly-promoted Prefixed id, not the stale primary_id.
419	        if let Some(keys) = self.path_native_keys.get(&existing_path) {
420	            for key in keys {
421	                self.index.native.insert(key.clone(), existing_id.clone());
422	            }
423	        }
424	        if let Some(keys) = self.path_native_keys.get(&rel_path) {
425	            for key in keys {
426	                self.index.native.insert(key.clone(), current_id.clone());
427	            }
428	        }
429	        // STALE-KEY REWRITE location (3)/(5): update index.prefixed values
430	        // for the primary identities so they point to the newly-promoted
431	        // Prefixed id rather than the pre-promotion primary_id.
432	        for eco in self
433	            .claiming_ecosystems
434	            .get(&existing_path)
435	            .cloned()
436	            .unwrap_or_default()
437	        {
438	            self.index.prefixed.insert((eco, name.clone()), existing_id.clone());
439	        }
440	        for eco in self.claiming_ecosystems.get(&rel_path).cloned().unwrap_or_default() {
441	            self.index.prefixed.insert((eco, name.clone()), current_id.clone());
442	        }
443	        // STALE-KEY REWRITE location (6): update index.platform's owner-id
444	        // component for every platform manifest declared under either path,
445	        // so a platform sibling co-located with a promoted owner keeps
446	        // pointing at that owner's newly-promoted Prefixed id rather than
447	        // the stale pre-promotion primary_id.
448	        if let Some(keys) = self.path_platform_keys.get(&existing_path) {
449	            for key in keys {
450	                if let Some((_, manifest_rel, role)) = self.index.platform.get(key).cloned() {
451	                    self.index
452	                        .platform
453	                        .insert(key.clone(), (existing_id.clone(), manifest_rel, role));
454	                }
455	            }
456	        }
457	        if let Some(keys) = self.path_platform_keys.get(&rel_path) {
458	            for key in keys {
459	                if let Some((_, manifest_rel, role)) = self.index.platform.get(key).cloned() {
460	                    self.index
461	                        .platform
462	                        .insert(key.clone(), (current_id.clone(), manifest_rel, role));
463	                }
464	            }
465	        }
466	        let existing_set = self
467	            .claiming_ecosystems
468	            .get(&existing_path)
469	            .cloned()
470	            .unwrap_or_default();
471	        let current_set = self.claiming_ecosystems.get(&rel_path).cloned().unwrap_or_default();
472	        self.promoted_siblings
473	            .entry(name.clone())
474	            .or_default()
475	            .extend([(existing_id, existing_set), (current_id, current_set)]);
476	    }
477	
478	    /// After every path is assigned, so each owner's id is final (post-promotion).
479	    fn attach_platforms(&mut self, attached_platforms: BTreeMap<PathBuf, (PathBuf, String, ManifestRole)>) {
480	        for (platform_dir, (owner_dir, name, role)) in attached_platforms {
481	            let manifest_rel = platform_dir.join("package.json");
482	            let owner = self.package_manifest_decls.iter_mut().find(|(_, (path, decls))| {
483	                *path == owner_dir && decls.iter().any(|d| d.format == ManifestFormat::PackageJson)
484	            });
485	            let Some((owner_id, (_, decls))) = owner else {
486	                continue;
487	            };
488	            match ManifestDecl::new(manifest_rel.clone(), role.clone(), ManifestFormat::PackageJson) {
489	                Ok(decl) => {
490	                    decls.push(decl);
491	                    self.index.platform.insert(name, (owner_id.clone(), manifest_rel, role));
492	                }
493	                Err(error) => self
494	                    .unresolved
495	                    .push(unresolved(&manifest_rel, "declare its platform manifest", error)),
496	            }
497	        }
498	    }
499	
500	    fn finish(self) -> Identified {
501	        Identified {
502	            package_manifest_decls: self.package_manifest_decls,
503	            index: self.index,
504	            promoted_siblings: self.promoted_siblings,
505	            unresolved: self.unresolved,
506	        }
507	    }
508	}
509	
510	/// Applies `[[package]]` and `[[package-set]]` rules to each identified package, then reports rules that matched
511	/// nothing or matched across ecosystems.
512	fn resolve_packages(
513	    package_manifest_decls: BTreeMap<PackageId, (PathBuf, Vec<ManifestDecl>)>,
514	    cfg: &ResolvedConfig,
515	    manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
516	    ctx: &OpenContext<'_>,
517	    diagnostics: &mut Vec<Diagnostic>,
518	) -> Result<BTreeMap<PackageId, Package>, GraphError> {
519	    // Tracks, per cfg.package_sets entry (by index), whether it matched at
520	    // least one real discovered package during this walk. A [[package-set]]
521	    // rule that matches nothing is almost always a typo or a stale
522	    // ecosystem prefix (see PackageSetMatchedNothing below) rather than
523	    // intentional, so it must be surfaced instead of silently ignored.
524	    let mut package_set_matched = vec![false; cfg.package_sets.len()];
525	
526	    // Same tracking, for `[[package]]` rules: an exact-id rule that matches zero real
527	    // packages (e.g. an ecosystem prefix the package doesn't actually have) is just as
528	    // likely a typo as an empty `[[package-set]]` glob, so it gets the same diagnostic.
529	    let mut package_rule_matched = vec![false; cfg.packages.len()];
530	
531	    let mut packages = BTreeMap::new();
532	    for (id, (rel_path, decls)) in package_manifest_decls {
533	        let ch_path = rel_path.join("CHANGELOG.md");
534	        let mut publish_to = Vec::new();
535	        // Attached platform manifests publish as their owner's platform operations, not as targets.
536	        for decl in decls.iter().filter(|d| d.role == ManifestRole::Canonical) {
537	            match open_cached(manifest_cache, decl, ctx) {
538	                Ok(editor) => {
539	                    for target in editor.publish_targets() {
540	                        if target != PublishTarget::None && !publish_to.contains(&target) {
541	                            publish_to.push(target);
542	                        }
543	                    }
544	                }
545	                Err(error) => diagnostics.push(unresolved(
546	                    &decl.path,
547	                    "open its manifest to read its publish targets",
548	                    error,
549	                )),
550	            }
551	        }
552	        if publish_to.is_empty() {
553	            publish_to.push(PublishTarget::None);
554	        }
555	
556	        // The real ecosystem(s) this package's manifests were discovered
557	        // in. `id` may be PackageId::Bare (unpromoted) or PackageId::Prefixed
558	        // (promoted); this is the
559	        // only place an ecosystem-prefixed [[package-set]] pattern has
560	        // anything to match against.

