564	        // Pass 1: find the first Prefixed rule (pattern.ecosystem().is_some())
565	        //         that matches this package's ID. Prefixed rules always win
566	        //         over Bare rules regardless of declaration order in callisto.toml.
567	        // Pass 2: only if pass 1 found nothing, find the first Bare rule
568	        //         (any rule, since no Prefixed rule matched, the first match
569	        //          is necessarily Bare) that matches this package's ID.
570	        // Within each pass, first-match-wins (TOML declaration order) applies.
571	        let pkg_override = resolve_package_config(&id, &package_ecosystems, cfg)?;
572	
573	        // Record which [[package-set]] patterns match this package,
574	        // independent of whether a [[package]] rule ends up shadowing the
575	        // fallback below — a pattern that is always shadowed still
576	        // "matched" for the purpose of the zero-match diagnostic.
577	        for (idx, (pattern, _)) in cfg.package_sets.iter().enumerate() {
578	            if pattern.matches_in_ecosystems(id.name(), &package_ecosystems) {
579	                package_set_matched[idx] = true;
580	            }
581	        }
582	        for (idx, (rule_id, _)) in cfg.packages.iter().enumerate() {
