679	                code: DiagnosticCode::PackageSetMatchedNothing,
680	                severity: DiagnosticSeverity::Warning,
681	                message: format!("[[package-set]] `{}` matched no packages", pattern.as_str()),
682	                package: None,
683	                path: None,
684	                escalated_by: None,
685	                governed_by: None,
