691	    // empty [[package-set]] match above (e.g. `cargo/foo` when `foo` only exists in npm) --
692	    // advisory for the same reason: a monorepo-wide callisto.toml against a partial checkout
693	    // can legitimately match nothing.
694	    for (idx, (rule_id, _)) in cfg.packages.iter().enumerate() {
