pub fn napi_drift(group: &GroupDef, declared: &[String], root: &Path) -> Vec<Diagnostic> {
    use crate::config::groups::GroupMemberKind;

    let declared_triples: BTreeSet<String> = declared.iter().map(|s| s.trim().to_string()).collect();

    let member_triples: BTreeSet<String> = group
        .members(GroupMemberKind::PlatformManifest)
        .filter_map(|m| match m {
            GroupMember::PlatformManifest { role, .. } => role_to_triple(role),
            _ => None,
        })
        .collect();

    let mut diagnostics = Vec::new();

    // Declared in napi.targets but no corresponding group member.
    for t in declared_triples.difference(&member_triples) {
        diagnostics.push(Diagnostic {
            code: DiagnosticCode::NapiTargetAddedNotInMembers,
            severity: DiagnosticSeverity::Warning,
            message: format!(
                "`napi.targets` declares `{t}`, which is not in fixed group `{}`'s members; accept it with `callisto init`",
                group.name
            ),
            package: None,
            path: None,
            governed_by: None,
            escalated_by: Some(StrictFlag::Strict),
        });
    }

    // Present in group members but removed from napi.targets — only warn if
    // the physical manifest file still exists on disk.
    for t in member_triples.difference(&declared_triples) {
        // Find the PlatformManifest whose triple matches t.
        let manifest_path = group.members(GroupMemberKind::PlatformManifest).find_map(|m| match m {
            GroupMember::PlatformManifest { role, path, .. } => {
                if role_to_triple(role).as_deref() == Some(t.as_str()) {
                    Some(root.join(path))
                } else {
                    None
                }
            }
    };
    let val: serde_json::Value = serde_json::from_str(&content).map_err(|e| {
        GraphError::Manifest(ManifestError::Parse {
            path: pkg_json_path.to_path_buf(),
            format: ManifestFormat::PackageJson,
            message: e.to_string(),
        })
    })?;
    Ok(Some(val))
}

/// Extracts `napi.targets` from an already-parsed `package.json` value (see
/// `parse_package_json`). A missing `napi` key or missing `napi.targets` key
/// is `Absent` (no platformTargets entry). A present `napi.targets`
/// that is not a JSON array of strings is a hard error -- strict
/// policy, propagating `callisto_manifests::read_napi_targets`'s error
/// as-is; unlike `NapiTargetsIndex::load`, which `.ok()`s the same shared
/// reader to silently drop non-array values instead.
pub(crate) fn read_napi_targets(pkg_json_path: &Path, val: &serde_json::Value) -> Result<NapiTargetsField, GraphError> {
    match callisto_manifests::read_napi_targets(pkg_json_path, val).map_err(GraphError::Manifest)? {
        Some(triples) => Ok(NapiTargetsField::Present(triples)),
        None => Ok(NapiTargetsField::Absent),
    }
}

/// Builds a PlatformTarget for `triple`, combining `triple_to_role`'s
/// platform/arch/abi with this module's hostRunner/useCross/artifactName
/// table. Returns `None` when `triple` is not recognised by either --
/// callers must route that case to an UnrecognisedPlatformTriple diagnostic
/// rather than treating it as an error.
pub(crate) fn build_platform_target(triple: &str, package_dir: &str, package_name: &str) -> Option<PlatformTarget> {
    let ManifestRole::Platform { platform, arch, abi } = triple_to_role(triple)? else {
        return None;
    };
    let (host_runner, use_cross) = triple_host_runner_use_cross(triple)?;
    let artifact_name = artifact_name_for_package_platform(package_name, &platform, &arch, abi.as_deref());
    Some(PlatformTarget {
        triple: triple.to_string(),
        platform,
        arch,
        abi,
        host_runner: host_runner.to_string(),
        use_cross,
        artifact_name,
        package_dir: package_dir.to_string(),
        package_name: package_name.to_string(),
        manifest_path: None,
    })
}

/// Reads and parses `pyproject_path` as TOML, if it exists. `Ok(None)` when
/// the file is absent -- not every package has a `pyproject.toml`.
///
/// Callers needing more than one field out of the same `pyproject.toml`
/// (e.g. both `[tool.maturin].targets` and `requires-python`, see
/// `build_matrix_report`) must call this once and pass the resulting
/// `Value` to each field-extraction function (`read_maturin_targets`,
/// `read_requires_python`) rather than letting each one independently
/// re-read and re-parse the file from disk.
pub(crate) fn parse_pyproject_toml(pyproject_path: &Path) -> Result<Option<toml::Value>, GraphError> {
    let Some(content) = callisto_model::strict_fs::read_optional(pyproject_path).map_err(|e| {
        GraphError::Manifest(ManifestError::Read {
            path: pyproject_path.to_path_buf(),
            message: e.to_string(),
        })
    })?
}

fn manifest_version_at<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    head: &str,
    path: &str,
    cargo_root: Option<&str>,
) -> Result<Option<callisto_manifests::EffectiveManifestVersion>, GraphError> {
    let path = std::path::Path::new(path);
    let Ok(format) = callisto_model::ManifestFormat::from_path(path) else {
        return Ok(None);
    };
    let Some(source) = manifest_blob_at(ws, head, &path.to_string_lossy())? else {
        return Ok(None);
    };
    Ok(callisto_manifests::read_effective_version(
        format,
        &source,
        path,
        cargo_root.map(|source| (std::path::Path::new("Cargo.toml"), source)),
    )?)
}

fn manifest_version_in_index<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    path: &str,
    cargo_root: Option<&str>,
) -> Result<Option<callisto_manifests::EffectiveManifestVersion>, GraphError> {
    let manifest_path = std::path::Path::new(path);
    let Ok(format) = callisto_model::ManifestFormat::from_path(manifest_path) else {
        return Ok(None);
    };
    let Some(source) = manifest_blob_in_index(ws, path)? else {
        return Ok(None);
    };
    callisto_manifests::read_effective_version(
        format,
        &source,
        manifest_path,
        cargo_root.map(|source| (std::path::Path::new("Cargo.toml"), source)),
    )
    .map_err(GraphError::from)
}

